package dev.legacyloader.profile;

import dev.legacyloader.api.LegacyProfile;
import dev.legacyloader.api.LifecyclePhase;

import java.util.EnumMap;
import java.util.Map;
/**
 * Forge 1.12.2 compatibility profile.
 *
 * <p>Adding another target means adding a sibling profile plus a shim source
 * set; no loader, discovery or runtime code needs to change. The shim index is
 * generated by Gradle from the corresponding source set.
 */
public final class Forge1122Profile implements LegacyProfile {
    public static final String ID = "forge-1.12.2";

    private static final Map<LifecyclePhase, String> EVENTS = new EnumMap<>(LifecyclePhase.class);

    static {
        EVENTS.put(LifecyclePhase.CONSTRUCT, "net.minecraftforge.fml.common.event.FMLConstructionEvent");
        EVENTS.put(LifecyclePhase.PRE_INIT, "net.minecraftforge.fml.common.event.FMLPreInitializationEvent");
        EVENTS.put(LifecyclePhase.INIT, "net.minecraftforge.fml.common.event.FMLInitializationEvent");
        EVENTS.put(LifecyclePhase.POST_INIT, "net.minecraftforge.fml.common.event.FMLPostInitializationEvent");
        EVENTS.put(LifecyclePhase.LOAD_COMPLETE, "net.minecraftforge.fml.common.event.FMLLoadCompleteEvent");
    }

    @Override
    public String id() {
        return ID;
    }

    @Override
    public String minecraftVersion() {
        return "1.12.2";
    }

    @Override
    public String shimIndexResource() {
        return "META-INF/legacyloader/shim-index-1.12.2.txt";
    }

    @Override
    public String modAnnotationClass() {
        return "net.minecraftforge.fml.common.Mod";
    }

    @Override
    public String eventHandlerAnnotationClass() {
        return "net.minecraftforge.fml.common.Mod$EventHandler";
    }

    @Override
    public String lifecycleEventClass(LifecyclePhase phase) {
        return EVENTS.get(phase);
    }

    @Override
    public String srgMappingsDirectory() {
        return "META-INF/legacyloader/mappings/1.12.2";
    }

    @Override
    public java.util.Set<String> providedMods() {
        // API-only compatibility package shipped with the loader.
        return java.util.Set.of("baubles");
    }

    @Override
    public boolean acceptsMinecraftVersion(String mcVersion) {        if (mcVersion == null) {
            return false;
        }
        String value = mcVersion.strip().toLowerCase();
        return value.equals("1.12") || value.equals("1.12.2") || value.startsWith("1.12.2-");
    }
}
